data=[(7,5,2),(1,7,3),(3,6,3),(4,5,2),(6,4,2),(2,3,1),(7,6,3),(4,7,3),(7,3,1),(2,7,3),(1,3,2),(2,4,3),(6,1,2),(8,4,3),(3,4,2),(7,6,3),(6,1,2),(8,4,3)]
# Test common modulo formulas a op b mod m, optional + constant, clipped to 3
ops={'+':lambda a,b:a+b,'-':lambda a,b:a-b,'r-':lambda a,b:b-a,'*':lambda a,b:a*b,'^':lambda a,b:a^b,'|':lambda a,b:a|b,'&':lambda a,b:a&b}
sol=[]
for name,f in ops.items():
 for m in range(2,21):
  for k in range(0,5):
   for clip in [False,True]:
    ok=True
    for c,h,n in data:
     try:v=f(c,h)%m+k
     except:ok=False;break
     if clip:v=min(3,v)
     if v!=n:ok=False;break
    if ok:sol.append((name,m,k,clip))
sol[:20],len(sol)

sol=[]
for name,f in ops.items():
 for mc in range(1,9):
  for mh in range(1,9):
   for k in range(0,4):
    for clip in [False,True]:
     if all((min(3,f(c%mc,h%mh)+k) if clip else f(c%mc,h%mh)+k)==n for c,h,n in data):sol.append((name,mc,mh,k,clip))
sol[:20]

sol=[]
for a in range(-5,6):
 for b in range(-5,6):
  if a==b==0:continue
  for k in range(-10,11):
   for d in range(1,11):
    for clip in [0,1]:
     if all((min(3,(a*c+b*h+k)//d) if clip else (a*c+b*h+k)//d)==n for c,h,n in data):sol.append((a,b,k,d,clip))
sol[:20],len(sol)
